from chess_part import ChessAnalyzer

def get_middlegame_analysis_response(PGN, FEN, played_move):
    chess_analyzer = ChessAnalyzer()
    chess_analyzer.load_position(FEN, played_move, PGN)
    if chess_analyzer.best == played_move:
        prompt = f"You are an expert chess coach specializing in the middle game which is the phase of the game. Your goal is to explain why the move {played_move} is strong and aligns with the engine's top recommendation, using concrete, intuitive reasoning based on the current board state. Here is the board position: {FEN} for your reference the places of the white pieces are {chess_analyzer.white_pieces} and the black pieces are {chess_analyzer.black_pieces}. {chess_analyzer.turn} played {played_move}, which matches the engine's best move. Evaluation: {chess_analyzer.score}. Engine's top line (Principal Variation): {chess_analyzer.pv}. Explain why {played_move} is the best move in this position. Focus on middlegame principles such as checks, captures, threats, the opponent’s plans, targeting weaknesses, improving poorly placed pieces, king safety, piece coordination, and careful pawn play. Base your explanation on the tactical or positional ideas visible in the current position and the concepts suggested by the engine's principal variation. Your explanation should be intuitive, phrased clearly using chess terminology, and limited to one paragraph."
    else:
        prompt = f"You are an expert chess coach specializing in the middle game which is the phase of the game. Your goal is to explain, in an intuitive way, why the engine's best move is superior to the move played by {chess_analyzer.turn}, based on the current board position and engine analysis. Here is the board position: {FEN} for your reference the places of the white pieces are {chess_analyzer.white_pieces} and the black pieces are {chess_analyzer.black_pieces}. {chess_analyzer.turn} played {played_move}, which led to an evaluation of {chess_analyzer.score_played}. The best move according to the engine was {chess_analyzer.best}, evaluated at {chess_analyzer.score}. Engine's top line (Principal Variation): {chess_analyzer.pv}. Explain only why {chess_analyzer.best} is tactically or positionally stronger than {played_move} in this exact position. Focus on middlegame principles such as identifying tactical threats, understanding the opponent’s plan, targeting weaknesses, improving poorly placed pieces, ensuring king safety, coordinating pieces effectively, and making careful pawn moves. Base your explanation on the tactical or positional ideas visible in the current position and the concepts suggested by the engine's principal variation. Your explanation should be intuitive, phrased clearly using standard chess terminology, and limited to one paragraph."

    print(prompt)